<?php
if(!defined('SCHOOLOS_OPERATIONS_LIBRARY')){header('Location: index.php?s=operations&area=boarding',true,302);exit;}
function bd_schema():array{return [
 "CREATE TABLE IF NOT EXISTS bd_hostel_settings(tenant_id BIGINT UNSIGNED NOT NULL,hostel_id BIGINT UNSIGNED NOT NULL,warden_user_id BIGINT UNSIGNED NOT NULL,fee_kobo BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,hostel_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS bd_rooms(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,hostel_id BIGINT UNSIGNED NOT NULL,name VARCHAR(100) NOT NULL,capacity INT NOT NULL,UNIQUE KEY room_name(tenant_id,hostel_id,name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS bd_beds(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,room_id BIGINT UNSIGNED NOT NULL,name VARCHAR(100) NOT NULL,UNIQUE KEY bed_name(tenant_id,room_id,name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS bd_allocations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,bed_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,starts_on DATE NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'active',released_at DATETIME NULL,INDEX(tenant_id,student_id,status),INDEX(tenant_id,bed_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS bd_presence(tenant_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,status VARCHAR(12) NOT NULL,updated_at DATETIME NOT NULL,PRIMARY KEY(tenant_id,student_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS bd_movements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,hostel_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,kind VARCHAR(12) NOT NULL,permit_id BIGINT UNSIGNED NULL,recorded_by BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL,INDEX(tenant_id,student_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS bd_leave(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,hostel_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,reason VARCHAR(2000) NOT NULL,collector VARCHAR(180) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',requested_by BIGINT UNSIGNED NOT NULL,approved_by BIGINT UNSIGNED NULL,identity_note VARCHAR(500) NULL,INDEX(tenant_id,hostel_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS bd_visitors(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,hostel_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,phone VARCHAR(40) NOT NULL,purpose VARCHAR(500) NOT NULL,identity_note VARCHAR(500) NOT NULL,arrived_at DATETIME NOT NULL,left_at DATETIME NULL,recorded_by BIGINT UNSIGNED NOT NULL,INDEX(tenant_id,hostel_id,left_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS bd_rollcalls(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,hostel_id BIGINT UNSIGNED NOT NULL,roll_date DATE NOT NULL,period VARCHAR(20) NOT NULL,recorded_by BIGINT UNSIGNED NOT NULL,UNIQUE KEY hostel_roll(tenant_id,hostel_id,roll_date,period)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS bd_roll_marks(tenant_id BIGINT UNSIGNED NOT NULL,rollcall_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,status VARCHAR(20) NOT NULL,note VARCHAR(500) NULL,PRIMARY KEY(tenant_id,rollcall_id,student_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS bd_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,hostel_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NULL,kind VARCHAR(20) NOT NULL,title VARCHAR(200) NOT NULL,body TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'open',created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,hostel_id,kind)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS bd_supplies(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,hostel_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,quantity INT NOT NULL DEFAULT 0,reorder_level INT NOT NULL DEFAULT 0,UNIQUE KEY stock_name(tenant_id,hostel_id,name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS bd_supply_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,supply_id BIGINT UNSIGNED NOT NULL,delta INT NOT NULL,note VARCHAR(500) NOT NULL,created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS bd_meals(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,hostel_id BIGINT UNSIGNED NOT NULL,meal_date DATE NOT NULL,title VARCHAR(180) NOT NULL,body VARCHAR(2000) NOT NULL,options_json TEXT NOT NULL,fee_kobo BIGINT NOT NULL DEFAULT 0,created_by BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS bd_meal_links(tenant_id BIGINT UNSIGNED NOT NULL,meal_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,post_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(tenant_id,meal_id,student_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS bd_meal_servings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,meal_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,choice VARCHAR(180) NOT NULL,note VARCHAR(500) NULL,recorded_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY serve_once(tenant_id,meal_id,student_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
];}
function bd_hostel(array $u,int $id):array{$h=op_own('hostels',$u,$id);if(!op_can($u,'boarding_manager')&&(!op_can($u,'warden')||!g('SELECT hostel_id FROM bd_hostel_settings WHERE tenant_id=? AND hostel_id=? AND warden_user_id=?',[$u['tenant_id'],$id,$u['id']])))throw new RuntimeException('Hostel is not assigned to this warden.');return $h;}
function bd_resident(array $u,int $sid):array{$r=q("SELECT a.*,r.hostel_id,r.name room_name,b.name bed_name FROM bd_allocations a JOIN bd_beds b ON b.id=a.bed_id AND b.tenant_id=a.tenant_id JOIN bd_rooms r ON r.id=b.room_id AND r.tenant_id=b.tenant_id WHERE a.tenant_id=? AND a.student_id=? AND a.status='active'",[$u['tenant_id'],$sid])->fetch();if(!$r)throw new RuntimeException('Active boarding allocation required.');return $r;}
function bd_action(array $u,string $a):string{
 global $pdo;$tid=(int)$u['tenant_id'];$uid=(int)$u['id'];$manager=op_can($u,'boarding_manager');
 if($a==='leave_request'){$sid=op_id('student_id');$r=bd_resident($u,$sid);if(in_array($u['role'],['parent','student'],true))op_child($u,$sid);else bd_hostel($u,(int)$r['hostel_id']);$start=op_datetime(op_text('starts_at',16,true));$end=op_datetime(op_text('ends_at',16,true));if($end<=$start||$end<=date('Y-m-d H:i:s'))throw new RuntimeException('Check the leave period.');q('INSERT INTO bd_leave(tenant_id,hostel_id,student_id,starts_at,ends_at,reason,collector,requested_by) VALUES(?,?,?,?,?,?,?,?)',[$tid,$r['hostel_id'],$sid,$start,$end,op_text('reason',2000,true),op_text('collector',180,true),$uid]);return 'Boarding leave permit requested; approval and identity check are still required.';}
 if($a==='hostel'){
  op_need($u,'boarding_manager');$warden=op_own('users',$u,op_id('warden_user_id'));if(!$warden['active']||!g("SELECT user_id FROM op_roles WHERE tenant_id=? AND user_id=? AND capability='warden'",[$tid,$warden['id']]))throw new RuntimeException('Grant warden access to an active employee account first.');$pdo->beginTransaction();try{q('INSERT INTO hostels(tenant_id,name,rooms) VALUES(?,?,0)',[$tid,op_text('name',150,true)]);$id=(int)$pdo->lastInsertId();q('INSERT INTO bd_hostel_settings(tenant_id,hostel_id,warden_user_id,fee_kobo) VALUES(?,?,?,?)',[$tid,$id,$warden['id'],op_money(op_text('fee',20,true),true)]);$pdo->commit();return 'Hostel registered with scoped warden and fee.';}catch(Throwable $e){$pdo->rollBack();throw $e;}
 }
 if($a==='configure_hostel'){op_need($u,'boarding_manager');$h=op_own('hostels',$u,op_id('hostel_id'));$warden=op_own('users',$u,op_id('warden_user_id'));if(!$warden['active']||!g("SELECT user_id FROM op_roles WHERE tenant_id=? AND user_id=? AND capability='warden'",[$tid,$warden['id']]))throw new RuntimeException('Grant active warden access first.');q('INSERT INTO bd_hostel_settings(tenant_id,hostel_id,warden_user_id,fee_kobo) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE warden_user_id=VALUES(warden_user_id),fee_kobo=VALUES(fee_kobo)',[$tid,$h['id'],$warden['id'],op_money(op_text('fee',20,true),true)]);return 'Existing hostel configured without replacing records.';}
 if($a==='room'){op_need($u,'boarding_manager');$h=bd_hostel($u,op_id('hostel_id'));$cap=op_id('capacity');if($cap<1||$cap>100)throw new RuntimeException('Room capacity must be 1–100.');q('INSERT INTO bd_rooms(tenant_id,hostel_id,name,capacity) VALUES(?,?,?,?)',[$tid,$h['id'],op_text('name',100,true),$cap]);return 'Hostel room added.';}
 if($a==='bed'){
  op_need($u,'boarding_manager');$r=op_own('bd_rooms',$u,op_id('room_id'));$pdo->beginTransaction();try{q('SELECT id FROM bd_rooms WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$r['id']]);if((int)g('SELECT COUNT(*) FROM bd_beds WHERE tenant_id=? AND room_id=?',[$tid,$r['id']])>=(int)$r['capacity'])throw new RuntimeException('Room bed capacity reached.');q('INSERT INTO bd_beds(tenant_id,room_id,name) VALUES(?,?,?)',[$tid,$r['id'],op_text('name',100,true)]);$pdo->commit();return 'Bed registered.';}catch(Throwable $e){$pdo->rollBack();throw $e;}
 }
 if($a==='allocate'||$a==='release'){
  op_need($u,'boarding_manager');$s=op_own('students',$u,op_id('student_id'));$pdo->beginTransaction();try{q('SELECT id FROM students WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$s['id']]);$old=q("SELECT * FROM bd_allocations WHERE tenant_id=? AND student_id=? AND status='active' FOR UPDATE",[$tid,$s['id']])->fetch();if($a==='release'){if(!$old)throw new RuntimeException('No active bed allocation.');if(g("SELECT student_id FROM bd_presence WHERE tenant_id=? AND student_id=? AND status='in'",[$tid,$s['id']]))throw new RuntimeException('Record authorised check-out before releasing the bed.');q('SELECT id FROM bd_beds WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$old['bed_id']]);q("UPDATE bd_allocations SET status='released',released_at=? WHERE tenant_id=? AND id=?",[date('Y-m-d H:i:s'),$tid,$old['id']]);}
   else{if($old)throw new RuntimeException('Student already has an active bed.');$bed=q('SELECT * FROM bd_beds WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,op_id('bed_id')])->fetch();if(!$bed||g("SELECT id FROM bd_allocations WHERE tenant_id=? AND bed_id=? AND status='active' LIMIT 1 FOR UPDATE",[$tid,$bed['id']]))throw new RuntimeException('Bed is occupied/unavailable.');$start=op_date(op_text('starts_on',10,true));if($start>date('Y-m-d'))throw new RuntimeException('Use an allocation start date of today or earlier. Future reservations are not active allocations.');q('INSERT INTO bd_allocations(tenant_id,bed_id,student_id,starts_on) VALUES(?,?,?,?)',[$tid,$bed['id'],$s['id'],$start]);}audit('boarding.'.$a,'student',(string)$s['id']);$pdo->commit();return 'Bed allocation updated with history retained.';
  }catch(Throwable $e){$pdo->rollBack();throw $e;}
 }
 if($a==='fee'){
  op_need($u,'boarding_manager');$sid=op_id('student_id');$pdo->beginTransaction();try{q('SELECT id FROM students WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$sid]);$r=bd_resident($u,$sid);$settings=q('SELECT * FROM bd_hostel_settings WHERE tenant_id=? AND hostel_id=?',[$tid,$r['hostel_id']])->fetch();if(!$settings)throw new RuntimeException('Configure hostel fee first.');op_fee($u,$sid,'BD',op_text('period',40,true),(int)$settings['fee_kobo'],'Boarding fee');$pdo->commit();return 'Boarding invoice generated once in Finance.';}catch(Throwable $e){$pdo->rollBack();throw $e;}
 }
 if($a==='leave_review'){$r=op_own('bd_leave',$u,op_id('permit_id'));bd_hostel($u,(int)$r['hostel_id']);$decision=op_text('status',20);if(!in_array($decision,['approved','rejected'],true)||$r['status']!=='pending'||(int)$r['requested_by']===$uid)throw new RuntimeException('A different reviewer must approve/reject a pending permit.');$st=q("UPDATE bd_leave SET status=?,approved_by=? WHERE tenant_id=? AND id=? AND status='pending'",[$decision,$uid,$tid,$r['id']]);if(!$st->rowCount())throw new RuntimeException('Permit changed; refresh.');return 'Boarding permit reviewed.';}
 if($a==='movement'){
  $sid=op_id('student_id');$r=bd_resident($u,$sid);bd_hostel($u,(int)$r['hostel_id']);$kind=op_text('kind',20);if(!in_array($kind,['in','out'],true))throw new RuntimeException('Invalid movement.');$pid=op_id('permit_id');$pdo->beginTransaction();try{q('SELECT id FROM students WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$sid]);$r=bd_resident($u,$sid);bd_hostel($u,(int)$r['hostel_id']);$current=q('SELECT * FROM bd_presence WHERE tenant_id=? AND student_id=? FOR UPDATE',[$tid,$sid])->fetch();if(($current['status']??'out')===$kind)throw new RuntimeException('Student is already recorded '.$kind.'.');$permit=null;
   if($kind==='out'){$permit=q('SELECT * FROM bd_leave WHERE tenant_id=? AND id=? AND student_id=? FOR UPDATE',[$tid,$pid,$sid])->fetch();$now=date('Y-m-d H:i:s');if(!$permit||$permit['status']!=='approved'||(int)$permit['hostel_id']!==(int)$r['hostel_id']||$permit['starts_at']>$now||$permit['ends_at']<$now||op_text('identity_checked',10)!=='yes'||mb_strlen(op_text('identity_note',500))<8)throw new RuntimeException('A current approved permit and physical collector identity check are required.');q("UPDATE bd_leave SET status='out',identity_note=? WHERE tenant_id=? AND id=?",[op_text('identity_note',500),$tid,$pid]);}
   else{if($current){$permit=q("SELECT * FROM bd_leave WHERE tenant_id=? AND student_id=? AND status='out' ORDER BY id DESC LIMIT 1 FOR UPDATE",[$tid,$sid])->fetch();if($permit){$pid=(int)$permit['id'];q("UPDATE bd_leave SET status='returned' WHERE tenant_id=? AND id=?",[$tid,$pid]);}}}
   q('INSERT INTO bd_presence(tenant_id,student_id,status,updated_at) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),updated_at=VALUES(updated_at)',[$tid,$sid,$kind,date('Y-m-d H:i:s')]);q('INSERT INTO bd_movements(tenant_id,hostel_id,student_id,kind,permit_id,recorded_by,created_at) VALUES(?,?,?,?,?,?,?)',[$tid,$r['hostel_id'],$sid,$kind,$pid?:null,$uid,date('Y-m-d H:i:s')]);$mid=(int)$pdo->lastInsertId();op_notify($u,$sid,'boarding','Boarding check-'.$kind.' recorded at '.date('H:i').' (Africa/Lagos).','BD-MOVE-'.$mid);$pdo->commit();return 'Boarding movement recorded and family notified in-app.';
  }catch(Throwable $e){$pdo->rollBack();throw $e;}
 }
 if($a==='visitor_in'){$sid=op_id('student_id');$r=bd_resident($u,$sid);bd_hostel($u,(int)$r['hostel_id']);if(op_text('identity_checked',10)!=='yes')throw new RuntimeException('Verify visitor identity before entry.');q('INSERT INTO bd_visitors(tenant_id,hostel_id,student_id,name,phone,purpose,identity_note,arrived_at,recorded_by) VALUES(?,?,?,?,?,?,?,?,?)',[$tid,$r['hostel_id'],$sid,op_text('name',180,true),op_text('phone',40,true),op_text('purpose',500,true),op_text('identity_note',500,true),date('Y-m-d H:i:s'),$uid]);return 'Visitor signed in by the hostel team.';}
 if($a==='visitor_out'){$r=op_own('bd_visitors',$u,op_id('visitor_id'));bd_hostel($u,(int)$r['hostel_id']);$st=q('UPDATE bd_visitors SET left_at=? WHERE tenant_id=? AND id=? AND left_at IS NULL',[date('Y-m-d H:i:s'),$tid,$r['id']]);if(!$st->rowCount())throw new RuntimeException('Visitor already signed out.');return 'Visitor signed out.';}
 if($a==='roll'){
  $sid=op_id('student_id');$r=bd_resident($u,$sid);bd_hostel($u,(int)$r['hostel_id']);$period=op_text('period',20);$status=op_text('status',20);$day=op_date(op_text('roll_date',10,true));if(!in_array($period,['morning','evening'],true)||!in_array($status,['present','absent','leave'],true)||$day>date('Y-m-d'))throw new RuntimeException('Check roll call date/period/status.');if($status==='leave'&&!g("SELECT id FROM bd_leave WHERE tenant_id=? AND student_id=? AND status IN ('out','returned') AND DATE(starts_at)<=? AND DATE(ends_at)>=? LIMIT 1",[$tid,$sid,$day,$day]))throw new RuntimeException('An authorised leave record is required for leave status.');$pdo->beginTransaction();try{q('INSERT IGNORE INTO bd_rollcalls(tenant_id,hostel_id,roll_date,period,recorded_by) VALUES(?,?,?,?,?)',[$tid,$r['hostel_id'],$day,$period,$uid]);$id=(int)g('SELECT id FROM bd_rollcalls WHERE tenant_id=? AND hostel_id=? AND roll_date=? AND period=?',[$tid,$r['hostel_id'],$day,$period]);q('INSERT INTO bd_roll_marks(tenant_id,rollcall_id,student_id,status,note) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),note=VALUES(note)',[$tid,$id,$sid,$status,op_text('note',500)]);if($status==='absent')op_notify($u,$sid,'boarding','Boarding roll call follow-up needed: '.$day.' '.$period.'.','BD-ROLL-'.$id.'-'.$sid);$pdo->commit();return 'Roll call recorded.';}catch(Throwable $e){$pdo->rollBack();throw $e;}
 }
 if($a==='event'){$h=bd_hostel($u,op_id('hostel_id'));$sid=op_id('student_id');if($sid&&(int)bd_resident($u,$sid)['hostel_id']!==(int)$h['id'])throw new RuntimeException('Student is in another hostel.');$kind=op_text('kind',20);if(!in_array($kind,['incident','maintenance','welfare'],true))throw new RuntimeException('Invalid hostel event.');$title=op_text('title',200,true);$body=op_text('body',3000,true);$pdo->beginTransaction();try{q('INSERT INTO bd_events(tenant_id,hostel_id,student_id,kind,title,body,created_by) VALUES(?,?,?,?,?,?,?)',[$tid,$h['id'],$sid?:null,$kind,$title,$body,$uid]);if($sid&&in_array($kind,['welfare','incident'],true))q("INSERT INTO aw_cases(tenant_id,student_id,kind,severity,title,details,confidential,created_by) VALUES(?,?,'boarding','medium',?,?,1,?)",[$tid,$sid,$title,$body,$uid]);$pdo->commit();return 'Private hostel event recorded; student welfare/incident also appears in Welfare.';}catch(Throwable $e){$pdo->rollBack();throw $e;}}
 if($a==='close_event'){$r=op_own('bd_events',$u,op_id('event_id'));bd_hostel($u,(int)$r['hostel_id']);q("UPDATE bd_events SET status='closed' WHERE tenant_id=? AND id=?",[$tid,$r['id']]);return 'Hostel event closed.';}
