 if($a==='stock'){$r=op_own('bd_supplies',$u,op_id('supply_id'));bd_hostel($u,(int)$r['hostel_id']);$raw=op_text('delta',10,true);if(!preg_match('/^-?\d{1,6}$/D',$raw)||(int)$raw===0)throw new RuntimeException('Enter a nonzero whole-unit stock adjustment.');$pdo->beginTransaction();try{$r=q('SELECT * FROM bd_supplies WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$r['id']])->fetch();if((int)$r['quantity']+(int)$raw<0)throw new RuntimeException('Cannot issue more stock than available.');q('UPDATE bd_supplies SET quantity=quantity+? WHERE tenant_id=? AND id=?',[(int)$raw,$tid,$r['id']]);q('INSERT INTO bd_supply_events(tenant_id,supply_id,delta,note,created_by) VALUES(?,?,?,?,?)',[$tid,$r['id'],(int)$raw,op_text('note',500,true),$uid]);$pdo->commit();return 'Stock adjustment recorded with an audit trail.';}catch(Throwable $e){$pdo->rollBack();throw $e;}}
 if($a==='meal'){$h=bd_hostel($u,op_id('hostel_id'));$opts=array_values(array_filter(array_map('trim',explode("\n",op_text('options',2000,true))),fn($v)=>$v!==''));if(!$opts||count($opts)>20)throw new RuntimeException('Use 1–20 meal choices.');foreach($opts as $opt)if(mb_strlen($opt)>180)throw new RuntimeException('Meal choice too long.');q('INSERT INTO bd_meals(tenant_id,hostel_id,meal_date,title,body,options_json,fee_kobo,created_by) VALUES(?,?,?,?,?,?,?,?)',[$tid,$h['id'],op_date(op_text('meal_date',10,true)),op_text('title',180,true),op_text('body',2000,true),json_encode($opts),op_money(op_text('fee',20,true),true),$uid]);return 'Menu created. Publish it to resident families below.';}
 if($a==='publish_meal'){
  $m=op_own('bd_meals',$u,op_id('meal_id'));bd_hostel($u,(int)$m['hostel_id']);$pdo->beginTransaction();try{q('SELECT id FROM bd_meals WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$m['id']]);$residents=q("SELECT a.student_id FROM bd_allocations a JOIN bd_beds b ON b.id=a.bed_id AND b.tenant_id=a.tenant_id JOIN bd_rooms r ON r.id=b.room_id AND r.tenant_id=b.tenant_id WHERE a.tenant_id=? AND r.hostel_id=? AND a.status='active' AND a.starts_on<=?",[$tid,$m['hostel_id'],$m['meal_date']])->fetchAll();foreach($residents as $r){if(g('SELECT post_id FROM bd_meal_links WHERE tenant_id=? AND meal_id=? AND student_id=?',[$tid,$m['id'],$r['student_id']]))continue;q("INSERT INTO pp_posts(tenant_id,kind,title,body,student_id,ends_at,options_json,created_by) VALUES(?,'meals',?,?,?,?,?,?)",[$tid,$m['title'],$m['body'],$r['student_id'],$m['meal_date'].' 23:59:59',$m['options_json'],$uid]);$post=(int)$pdo->lastInsertId();q('INSERT INTO bd_meal_links(tenant_id,meal_id,student_id,post_id) VALUES(?,?,?,?)',[$tid,$m['id'],$r['student_id'],$post]);}$pdo->commit();return 'Menu published to allocated residents in Family Space; existing choices preserved.';}catch(Throwable $e){$pdo->rollBack();throw $e;}
 }
 if($a==='serve'){
  $m=op_own('bd_meals',$u,op_id('meal_id'));bd_hostel($u,(int)$m['hostel_id']);$sid=op_id('student_id');$choice=op_text('choice',180,true);$pdo->beginTransaction();try{q('SELECT id FROM students WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$sid]);$r=bd_resident($u,$sid);if((int)$r['hostel_id']!==(int)$m['hostel_id']||$m['meal_date']!==date('Y-m-d')||!in_array($choice,json_decode($m['options_json'],true),true))throw new RuntimeException('Check resident, meal date and choice.');$response=q('SELECT p.answer FROM bd_meal_links l JOIN pp_responses p ON p.post_id=l.post_id AND p.tenant_id=l.tenant_id AND p.student_id=l.student_id WHERE l.tenant_id=? AND l.meal_id=? AND l.student_id=? ORDER BY p.updated_at DESC,p.id DESC LIMIT 1',[$tid,$m['id'],$sid])->fetch();$note=op_text('note',500);if((!$response||$response['answer']!==$choice)&&mb_strlen($note)<8)throw new RuntimeException('Explain a staff-selected meal or change to the family choice.');q('INSERT INTO bd_meal_servings(tenant_id,meal_id,student_id,choice,note,recorded_by) VALUES(?,?,?,?,?,?)',[$tid,$m['id'],$sid,$choice,$note,$uid]);if((int)$m['fee_kobo']>0)op_fee($u,$sid,'MEAL',(string)$m['id'],(int)$m['fee_kobo'],$m['title']);$pdo->commit();return 'Meal serving recorded once; configured charge is in Finance.';}catch(Throwable $e){$pdo->rollBack();throw $e;}
