 $residents=q("SELECT a.student_id id,s.name,a.bed_id,r.hostel_id,r.name room,b.name bed,COALESCE(p.status,'out') presence FROM bd_allocations a JOIN students s ON s.id=a.student_id AND s.tenant_id=a.tenant_id JOIN bd_beds b ON b.id=a.bed_id AND b.tenant_id=a.tenant_id JOIN bd_rooms r ON r.id=b.room_id AND r.tenant_id=b.tenant_id LEFT JOIN bd_presence p ON p.student_id=a.student_id AND p.tenant_id=a.tenant_id WHERE a.tenant_id=? AND a.status='active' AND r.hostel_id IN ($in) ORDER BY s.name",[$tid])->fetchAll();$sc=op_choices($residents);
 $tabs=['dashboard'=>'Warden dashboard & occupancy','rooms'=>'Hostels, rooms & beds','allocations'=>'Bed allocation','fees'=>'Fees','movements'=>'Check-in / out','leave'=>'Leave permits','visitors'=>'Visitors','roll'=>'Roll calls','incidents'=>'Incidents & welfare','maintenance'=>'Maintenance','supplies'=>'Supplies','meals'=>'Meals'];$view=is_string($_GET['view']??null)?$_GET['view']:'dashboard';if(!isset($tabs[$view]))$view='dashboard';echo '<nav class="op-nav">';foreach($tabs as $k=>$v)echo '<a href="?s=operations&amp;area=boarding&amp;view='.$k.'">'.e($v).'</a>';echo '</nav>';op_card($tabs[$view]);
 if($view==='dashboard'){
